arguments.command:
python3 -c "import pandas as pd; df = pd.read_csv('quarterly_sales.csv'); total_revenue = df['Revenue'].sum(); total_profit = (df['Revenue'] - df['Cost']).sum(); total_units = df['Units_Sold'].sum(); top_region = df.groupby('Region')['Revenue'].sum().idxmax(); top_region_revenue = df.groupby('Region')['Revenue'].sum().max(); top_product = df.groupby('Product')['Revenue'].sum().idxmax(); top_product_revenue = df.groupby('Product')['Revenue'].sum().max(); print(f'Total Revenue: {total_revenue}
Total Profit: {total_profit}
Total Units Sold: {total_units}
Top Region: {top_region} (${top_region_revenue})
Top Product: {top_product} (${top_product_revenue})')"
